#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    const long long MOD = 1000000007LL;
    long long a = n, b = n + 1;
    if (a % 2 == 0) {
        a /= 2;
    } else {
        b /= 2;
    }
    cout << (a % MOD) * (b % MOD) % MOD << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        final long MOD = 1000000007L;
        long a = n, b = n + 1;
        if (a % 2 == 0) {
            a /= 2;
        } else {
            b /= 2;
        }
        System.out.println((a % MOD) * (b % MOD) % MOD);
    }
}
